import{_ as l,a0 as o,w as d,s as r,ao as t,I as p,a1 as e,A as i,x as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 Linux 中恢复仍在活动进程中的已删除文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中恢复仍在活动进程中的已删除文件 | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中恢复仍在活动进程中的已删除文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中恢复仍在活动进程中的已删除文件 | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170714 HOW TO RECOVER DELETED FILES STILL RUNNING WITH ACTIVE PROCESSES ON LINUX","title":"如何在 Linux 中恢复仍在活动进程中的已删除文件","tag":"201707","desc":""},"relativePath":"201707/20170714 HOW TO RECOVER DELETED FILES STILL RUNNING WITH ACTIVE PROCESSES ON LINUX.md","filePath":"[post].md"}'),g={name:"201707/20170714 HOW TO RECOVER DELETED FILES STILL RUNNING WITH ACTIVE PROCESSES ON LINUX.md"};function h(c,s,u,k,m,b){const n=o("Link");return d(),r("div",null,[s[14]||(s[14]=t(`<h1 id="如何在-linux-中恢复仍在活动进程中的已删除文件" tabindex="-1">如何在 Linux 中恢复仍在活动进程中的已删除文件 <a class="header-anchor" href="#如何在-linux-中恢复仍在活动进程中的已删除文件" aria-label="Permalink to “如何在 Linux 中恢复仍在活动进程中的已删除文件”">​</a></h1><blockquote><p>使用终端恢复你 Linux 系统上仍在运行进程的已删除文件的快速指南。</p></blockquote><p>许多情况下，删除的文件都可以恢复，比如在该文件有活动的进程在操作它，并且目前被单个或多个用户使用时。在 Linux 系统中，每个当前正在运行的进程都会获得 ID，其被称之为进程标识符 “PID”，并将它们存放在 <code>/proc</code> 目录中。这正是我们恢复仍在运行的进程中（具有PID）已删除的文件所需要的东西。这里就是介绍我们如何做到这一点的。</p><p>假设你打开了一个压缩文件，之后你删除了这个文件。为了演示目的，压缩文件称为 “opengapps.zip”，这将是之后我们将打开和删除的文件。</p><h3 id="计算原始文件的-md5-哈希" tabindex="-1">计算原始文件的 MD5 哈希 <a class="header-anchor" href="#计算原始文件的-md5-哈希" aria-label="Permalink to “计算原始文件的 MD5 哈希”">​</a></h3><p>删除之前，我们将计算该文件的 MD5。这样我们可以将原来的 MD5 哈希值与恢复文件的 MD5 哈希进行比较。这个过程将保证我们恢复的压缩文件的完整性是一样的，它没有被破坏。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>md5sum opengapps.zip &gt;&gt; md5-opengapps.txt</span></span></code></pre></div><p>要显示文本文件的内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat md5-opengapps.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>86489b68b40d144f0e00a0ea8407f7c0  opengapps.zip</span></span></code></pre></div><p>检查压缩文件的 MD5 哈希值之后。我们将压缩文件保持打开（LCTT 译注：此处是使用 file-roller 这个图形界面的解压程序保持对该压缩文件的打开，其内置在 GNOME 环境中；在桌面环境中，使用桌面工具打开一个压缩包也能起到同样的作用。又及，本文举例不是很恰当，如果是删除了某个服务进程的已经打开的配置文件，那么这种恢复就很有意义），并将其删除。之后，我们将从文件的恢复过程开始，步骤如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm opengapps.zip</span></span></code></pre></div><h3 id="删除文件的恢复过程" tabindex="-1">删除文件的恢复过程 <a class="header-anchor" href="#删除文件的恢复过程" aria-label="Permalink to “删除文件的恢复过程”">​</a></h3><p>正如我们前面提到的，运行的进程在 <code>/proc</code> 目录中。我们可以使用以下命令搜索该目录中需要的进程：</p><p>由于我们已经知道文件名包括 .zip 扩展名，因此我们可以使用 .zip 扩展名进行搜索。它将限制输出结果并显示所需的进程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ps -axu | grep .zip</span></span>
<span class="line"><span></span></span>
<span class="line"><span>m        13119  0.8  1.0 121788 30788 ?        Sl   06:17   0:00 file-roller /home/m/Downloads/Compressed/opengapps.zip</span></span>
<span class="line"><span>m        13164  0.0  0.0   5108   832 pts/20   S+   06:18   0:00 grep --color=auto .zip</span></span></code></pre></div><p>然后我们将进入到包含 PID <code>13119</code> 的目录并打开 <code>fd</code> 子目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /proc/13119/fd</span></span></code></pre></div><p><code>fd</code> （文件描述符）目录包含多个文件，包括我们需要恢复的文件。该文件以硬链接的方式链接到原始文件。 <code>fd</code> 目录中的所有文件都以数字链接到“文件名”。因此，要确定这些文件中的哪一个链接到该原始文件，我们将用详细列表选项列出 /fd 目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -l</span></span>
<span class="line"><span></span></span>
<span class="line"><span>total 0</span></span>
<span class="line"><span>lr-x------ 1 m m 64 Jul 14 06:17 0 -&gt; /dev/null</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 1 -&gt; socket:[26161]</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 10 -&gt; anon_inode:[eventfd]</span></span>
<span class="line"><span>lr-x------ 1 m m 64 Jul 14 06:17 11 -&gt; anon_inode:inotify</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 12 -&gt; socket:[5752671]</span></span>
<span class="line"><span>lr-x------ 1 m m 64 Jul 14 06:17 13 -&gt; /home/m/Downloads/Compressed/opengapps.zip (deleted)</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 2 -&gt; socket:[26161]</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 3 -&gt; anon_inode:[eventfd]</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 4 -&gt; anon_inode:[eventfd]</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 5 -&gt; socket:[5751361]</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 6 -&gt; anon_inode:[eventfd]</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 7 -&gt; anon_inode:[eventfd]</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 8 -&gt; socket:[5751363]</span></span>
<span class="line"><span>lrwx------ 1 m m 64 Jul 14 06:17 9 -&gt; socket:[5751365]</span></span></code></pre></div><p>正如你在终端输出中看到的，原始文件 “opengapps.zip” 已被删除，但它仍然链接到一个文件名 <code>13</code>，其进程 PID <code>13119</code>。但是，我们仍然可以通过将链接的文件复制到安全的地方来恢复它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp 13 /home/m/Downloads/Compressed</span></span></code></pre></div><p>文件复制后。我们将返回包含恢复文件的目录，并使用以下命令重命名它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mv 13 opengapps-recovered.zip</span></span></code></pre></div><h3 id="计算恢复文件的-md5-哈希" tabindex="-1">计算恢复文件的 MD5 哈希 <a class="header-anchor" href="#计算恢复文件的-md5-哈希" aria-label="Permalink to “计算恢复文件的 MD5 哈希”">​</a></h3><p>由于我们已经恢复了该文件。让我们检查该文件的完整性，这只是为了确保文件没有损坏，并且和原来一样。早先我们保存了原始文件的 MD5 哈希值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>md5sum opengapps-recovered.zip &gt;&gt; md5-opengapps.txt</span></span></code></pre></div><p>该命令将检查文件的 MD5 哈希值，并在文件中追加新恢复文件的 MD5 哈希值，以轻松比较两个 MD5 哈希值。</p><p>可以显示文本文件的内容来比较原始文件和恢复文件的 MD5 哈希值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat md5-opengapps.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>86489b68b40d144f0e00a0ea8407f7c0  opengapps.zip</span></span>
<span class="line"><span>86489b68b40d144f0e00a0ea8407f7c0  opengapps-recovered.zip</span></span></code></pre></div><p>恢复文件的 MD5 哈希是一样的。所以，我们成功地恢复了我们以前删除的文件，并且恢复后文件完整性一致，并且工作正常。</p>`,30)),p("p",null,[e(n,{href:"http://www.linuxnov.com/wp-content/uploads/2017/07/Recovering-a-deleted-file-using-terminal-LinuxNov.png"},{default:i(()=>[...s[0]||(s[0]=[p("img",{src:"http://www.linuxnov.com/wp-content/uploads/2017/07/Recovering-a-deleted-file-using-terminal-LinuxNov.png",alt:""},null,-1)])]),_:1})]),s[15]||(s[15]=t('<p><strong>注意：</strong> 在某些情况下，某些文件无法通过 <code>ps -axu</code> 命令看到。 所以，尝试检查运行的程序，并从中恢复文件。</p><p>假设我们有一个使用 Totem 媒体播放器播放中的以 .avi 为扩展名的视频。你需要做的就是检查 Totem 的 PID，并按照本示例中提到的相同说明进行操作。</p><p>要查找正在运行的程序的 PID，请使用以下命令，后面跟程序的名称。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pidof 程序名</span></span></code></pre></div><p>通过分享支持我们。</p><hr>',6)),p("p",null,[s[2]||(s[2]=a("via: ",-1)),e(n,{href:"http://www.linuxnov.com/recover-deleted-files-still-running-active-processes-linux/"},{default:i(()=>[...s[1]||(s[1]=[a("http://www.linuxnov.com/recover-deleted-files-still-running-active-processes-linux/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"http://www.linuxnov.com/author/mhnassif/"},{default:i(()=>[...s[3]||(s[3]=[a("mhnassif",-1)])]),_:1}),s[7]||(s[7]=a(" 译者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[8]||(s[8]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[11]||(s[11]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[9]||(s[9]=[a("LCTT",-1)])]),_:1}),s[12]||(s[12]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[10]||(s[10]=[a("Linux中国",-1)])]),_:1}),s[13]||(s[13]=a(" 荣誉推出",-1))])])}const T=l(g,[["render",h]]);export{C as __pageData,T as default};
